            questions = "¿Qué función cumple en el tratamiento actual? ¿Cuáles señales de glucosa baja pueden ser menos evidentes en una persona mayor? ¿Qué plan escrito debemos tener? ¿Hay interacciones con sus otros medicamentos?",
            relatedQuestions = listOf(
