            source = DrugReference("Sovereign Medical / emc", "Tolbutamide Tablets BP: SmPC", "https://www.medicines.org.uk/emc/product/14621/smpc", "Revisión 15/01/2026").copy(reviewedOn = "22 de noviembre de 2026"),
