        card(
            id = "empagliflozina", name = "Empagliflozina", family = "Inhibidores SGLT2",
            aliases = listOf("empagliflozin"),
            summary = "La empagliflozina pertenece a los inhibidores SGLT2: ayuda a que los riñones eliminen glucosa en la orina.",
            use = "La ficha estadounidense describe su uso para mejorar el control de glucosa en diabetes tipo 2 y para reducir determinados riesgos en personas seleccionadas con insuficiencia cardiaca o enfermedad renal crónica. Son indicaciones diferentes: recibirla no significa necesariamente que se tengan todas esas enfermedades.\n\nEl beneficio que se busca y si el producto es adecuado dependen de una valoración profesional. La ficha de otro país tampoco confirma su disponibilidad o autorización en México.",
            mechanism = "Los riñones filtran la sangre. Parte de la glucosa filtrada se recupera y vuelve a la circulación mediante una proteína transportadora llamada SGLT2. La empagliflozina bloquea ese transporte, de modo que una mayor cantidad de glucosa sale en la orina.\n\nNo es insulina y no funciona pidiendo al páncreas que libere más. También modifica la recuperación de sodio y agua por el riñón; sus posibles efectos cardiovasculares o renales no deben resumirse como si solo se debieran a eliminar azúcar. La respuesta puede variar según la función renal y el objetivo de uso.",
            common = "Se han descrito infecciones urinarias, infecciones genitales por hongos y aumento de la cantidad de orina. La presencia de más glucosa en la orina forma parte del mecanismo del medicamento; algunas personas pueden presentar molestias, pero no todas desarrollan una infección.\n\nPicazón, enrojecimiento o molestias genitales y ardor al orinar son cambios que conviene comunicar. El profesional puede valorar su causa y gravedad; Bitavida no identifica una infección a partir de un síntoma.",
            serious = "La cetoacidosis es una acumulación peligrosa de ácidos llamados cetonas. Puede presentarse incluso cuando la glucosa no está muy elevada. Náuseas o vómitos, dolor abdominal, cansancio intenso y dificultad para respirar son señales descritas en la ficha que justifican atención urgente ante una sospecha.\n\nDolor, sensibilidad, enrojecimiento o hinchazón en la zona genital o entre genitales y ano, especialmente junto con fiebre o malestar, pueden acompañar una infección grave poco frecuente y necesitan atención urgente. También deben valorarse las señales de infección urinaria grave o pérdida importante de líquidos.",
            contraindications = "La ficha consultada contraindica su uso ante una reacción grave de hipersensibilidad a empagliflozina o a sus componentes.",
            precautions = "Al salir más glucosa por la orina también puede aumentar la pérdida de líquido. Los adultos mayores y las personas con enfermedad renal o que usan diuréticos pueden ser más vulnerables a efectos por disminución del volumen de líquido. El equipo puede revisar la función renal y la situación de hidratación.\n\nUna enfermedad, menor ingesta, ayuno o cirugía pueden cambiar los riesgos. Pide al equipo tratante las instrucciones correspondientes y no suspendas ni reinicies medicamentos por cuenta propia.",
            interactions = "Los diuréticos favorecen la eliminación de agua y, junto con empagliflozina, pueden aumentar la pérdida de líquido. La combinación con insulina o sulfonilureas puede aumentar el riesgo de glucosa baja. También se describe una posible disminución de la concentración de litio en sangre.\n\nLa presencia de una interacción no indica por sí misma que una persona deba suspender su tratamiento. El médico o farmacéutico necesita revisar el conjunto de productos y decidir qué seguimiento corresponde.",
            formulations = "Se presenta en comprimidos orales. La ficha consultada es estadounidense y no confirma disponibilidad o autorización de una presentación concreta en México.",
            questions = "¿Qué objetivo tiene en este plan? ¿Qué señales de infección o pérdida de líquido debemos comunicar? ¿Qué instrucciones debemos solicitar si la persona enferma o tendrá un procedimiento? ¿Hay interacciones que revisar?",
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Por qué sale glucosa en la orina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué molestias urinarias o genitales conviene comunicar?", DrugIntent.SIDE_EFFECTS),
                DrugRelatedQuestion("¿Por qué importa la pérdida de líquidos?", DrugIntent.PRECAUTIONS),
            ),
            source = daily("Jardiance: empagliflozin", "faf3dd6a-9cd0-39c2-0d2e-232cb3f67565", "Actualización 10/11/2026; revisión 01/2026").copy(reviewedOn = "22 de noviembre de 2026"),
        ),
        card(
            id = "dapagliflozina", name = "Dapagliflozina", family = "Inhibidores SGLT2",
            aliases = listOf("dapagliflozin"),
            summary = "La dapagliflozina es un inhibidor SGLT2: reduce la recuperación de glucosa filtrada por los riñones y aumenta su salida en la orina.",
            use = "La ficha estadounidense contempla mejorar el control de la glucosa en diabetes tipo 2 y reducir ciertos riesgos en personas seleccionadas con insuficiencia cardiaca o enfermedad renal crónica. Son objetivos distintos; recibir este medicamento no significa que una persona tenga todas esas condiciones.\n\nLa función renal y el propósito de la indicación influyen en la valoración del equipo tratante. Una ficha de otro país no confirma autorización ni disponibilidad en México.",
            mechanism = "Los riñones filtran la sangre y recuperan parte de la glucosa mediante un transportador llamado SGLT2. La dapagliflozina lo inhibe, de modo que menos glucosa regresa a la sangre y una mayor cantidad sale en la orina.\n\nNo es insulina ni estimula al páncreas para liberarla. La ficha indica que, por este mecanismo, una prueba de glucosa en orina puede resultar positiva; ese dato aislado no permite interpretar el tratamiento de una persona.",
            common = "Se describen infecciones genitales por hongos, infecciones urinarias y molestias respiratorias superiores. También puede aumentar la cantidad de orina. Picazón o molestias genitales y ardor al orinar son cambios que conviene comunicar; no todas las personas tienen estos efectos y la aplicación no diagnostica su causa.",
            serious = "La cetoacidosis es una acumulación peligrosa de ácidos llamados cetonas; puede presentarse incluso sin una glucosa muy elevada. Náuseas, vómitos, dolor abdominal, cansancio intenso o dificultad para respirar requieren atención urgente ante sospecha.\n\nDolor, enrojecimiento o hinchazón genital o entre los genitales y el ano, especialmente con fiebre o malestar, pueden acompañar una infección grave poco frecuente y requieren atención urgente. También se han comunicado infecciones urinarias graves y daño renal relacionado con pérdida de líquidos.",
            contraindications = "Antecedente de reacción grave de hipersensibilidad a dapagliflozina o sus componentes.",
            precautions = "Los adultos mayores y quienes tienen enfermedad renal o usan diuréticos pueden ser más vulnerables a pérdida de líquido o presión baja. El equipo puede revisar la función renal y la situación de hidratación. Una enfermedad, menor ingesta, ayuno o cirugía requieren instrucciones profesionales específicas; no suspendas ni reinicies el medicamento por tu cuenta.",
            interactions = "Los diuréticos pueden aumentar la pérdida de líquido; la insulina y las sulfonilureas pueden aumentar el riesgo de glucosa baja cuando se combinan con dapagliflozina. También puede disminuir la concentración de litio. El médico o farmacéutico debe revisar todos los productos, pues esta lista no confirma compatibilidad individual.",
            formulations = "La fuente describe comprimidos orales de dapagliflozina. También existen productos con otros principios activos y cada uno tiene información propia. Las condiciones de uso dependen de la indicación y no se deben inferir solo por compartir la familia SGLT2.",
            questions = "¿Qué objetivo busca este medicamento en el plan? ¿Qué señales de pérdida de líquido o infección debemos comunicar? ¿Qué plan debemos solicitar si la persona enferma o se somete a un procedimiento? ¿Cómo se revisará la función renal?",
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Por qué puede aparecer glucosa en la orina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué molestias urinarias o genitales se han descrito?", DrugIntent.SIDE_EFFECTS),
                DrugRelatedQuestion("¿Por qué se revisan los diuréticos?", DrugIntent.INTERACTIONS),
            ),
            source = daily("Farxiga: dapagliflozin", "72ad22ae-efe6-4cd6-a302-98aaee423d69", "Actualización 03/06/2026").copy(reviewedOn = "22 de noviembre de 2026"),
        ),
        card(
            id = "canagliflozina", name = "Canagliflozina", family = "Inhibidores SGLT2",
            aliases = listOf("canagliflozin"),
            summary = "La canagliflozina es un inhibidor SGLT2: actúa en el riñón para aumentar la eliminación de glucosa en la orina.",
            use = "La ficha estadounidense contempla su uso para mejorar el control de glucosa en diabetes tipo 2 y para reducir determinados riesgos cardiovasculares o renales en grupos específicos. Esos objetivos no significan que el medicamento sea adecuado para todas las personas ni que cada usuario tenga las mismas enfermedades.",
            mechanism = "Cuando los riñones filtran la sangre, un transportador llamado SGLT2 recupera parte de la glucosa filtrada y la devuelve a la circulación. Canagliflozina inhibe ese transporte, así que más glucosa sale por la orina.\n\nNo aporta insulina ni estimula su liberación por el páncreas. El equipo debe considerar la función renal y la indicación concreta; el efecto no permite inferir por sí mismo el estado de una persona.",
            common = "Se describen infecciones genitales por hongos, infección urinaria y aumento de la cantidad de orina. Picazón, enrojecimiento o molestias genitales y ardor al orinar son cambios que conviene comunicar al equipo. Estos efectos no aparecen en todas las personas y pueden tener otras causas.",
            serious = "La cetoacidosis es una acumulación peligrosa de ácidos llamados cetonas y puede ocurrir aunque la glucosa no esté muy elevada. Vómitos, dolor abdominal, cansancio intenso o dificultad para respirar justifican atención urgente ante sospecha. Dolor o hinchazón genital o del área entre genitales y ano con fiebre o malestar también requieren atención urgente.\n\nLa ficha advierte que en ciertos estudios se observó más riesgo de amputación de extremidades inferiores. Las lesiones, úlceras o infecciones nuevas en pies o piernas deben comunicarse al equipo. También se han documentado fracturas y pérdida importante de líquidos; esto no significa que vayan a ocurrir en cada persona.",
            contraindications = "Reacción grave de hipersensibilidad a canagliflozina.",
            precautions = "La edad avanzada, enfermedad renal y uso de diuréticos pueden aumentar los problemas relacionados con pérdida de líquido. El equipo también necesita conocer antecedentes de úlceras, amputación o problemas de circulación y sensibilidad en las piernas, pues se relacionan con el riesgo descrito en la ficha.\n\nPregunta qué hacer ante una lesión nueva o si la persona enferma o tendrá una cirugía. No interrumpas ni cambies un tratamiento basándote solo en la biblioteca.",
            interactions = "Los diuréticos pueden aumentar la pérdida de líquido y la combinación con insulina o sulfonilureas elevar el riesgo de glucosa baja. Rifampicina y otros medicamentos pueden modificar la concentración de canagliflozina; la ficha también advierte interacción con digoxina.\n\nLa lista no es completa. Un profesional debe revisar los productos recetados, los de venta libre y los suplementos antes de decidir qué vigilancia corresponde.",
            formulations = "La fuente describe comprimidos orales. Compartir familia con otra gliflozina no hace que todos los productos tengan las mismas indicaciones o advertencias; comprueba el nombre completo del envase.",
            questions = "¿Qué objetivo busca este medicamento en el plan? ¿Qué cambios en pies o piernas debemos comunicar? ¿Cómo se revisarán la función renal y la pérdida de líquido? ¿Qué indicaciones debemos pedir antes de una cirugía o si la persona enferma?",
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Por qué sale glucosa en la orina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué antecedentes de pies o circulación necesita conocer el equipo?", DrugIntent.PRECAUTIONS),
                DrugRelatedQuestion("¿Por qué se revisan los diuréticos y la digoxina?", DrugIntent.INTERACTIONS),
