        card(
            id = "sitagliptina", name = "Sitagliptina", family = "Inhibidores DPP-4",
            aliases = listOf("sitagliptin"),
            summary = "La sitagliptina es un inhibidor DPP-4 que prolonga la acción de señales intestinales relacionadas con la glucosa.",
            use = "La ficha estadounidense describe sitagliptina para mejorar el control de la glucosa en adultos con diabetes tipo 2 junto con las medidas acordadas con el equipo de salud. El profesional explica el objetivo de la indicación y cómo se revisará con el tiempo.\n\nLa ficha no determina por sí sola qué tratamiento necesita una persona. La referencia también distingue esta tableta de los productos que combinan sitagliptina con otros principios activos." ,
            mechanism = "Después de comer, el intestino libera señales llamadas incretinas. Estas ayudan al páncreas a liberar insulina cuando la glucosa está elevada y a disminuir la liberación de glucagón, una hormona que favorece que el hígado libere glucosa.\n\nUna enzima llamada DPP-4 descompone esas señales. La sitagliptina la bloquea para que actúen durante más tiempo. No es insulina y funciona de manera distinta a la metformina, que reduce principalmente la producción de glucosa del hígado." ,
            common = "En estudios se notificaron molestias de vías respiratorias superiores y dolor de cabeza. Los efectos pueden variar y no aparecen en todas las personas. Si una molestia persiste o interfiere con las actividades, comunícala al equipo para que valore su causa.\n\nEl riesgo de glucosa demasiado baja puede aumentar cuando se usa junto con insulina o una sulfonilurea. Sus señales pueden incluir hambre, temblor, sudoración o confusión y varían entre personas." ,
            serious = "La ficha describe pancreatitis, una inflamación del páncreas: un dolor abdominal intenso y persistente, a veces hacia la espalda y con o sin vómitos, requiere valoración urgente. También se han notificado problemas renales, dolor intenso en articulaciones y una enfermedad de la piel con ampollas.\n\nComunica pronto esos cambios al equipo. Hinchazón de cara, labios o garganta y dificultad para respirar requieren atención urgente por posible reacción alérgica grave. La aplicación no puede identificar la causa de un síntoma." ,
            contraindications = "La ficha consultada contraindica el producto si hubo una reacción grave a sitagliptina, como anafilaxia o hinchazón importante de cara o garganta.",
            precautions = "Los riñones participan en la eliminación de sitagliptina. La ficha indica revisar su función para valorar la presentación y el seguimiento adecuados; esto es especialmente relevante en adultos mayores.\n\nComunica antecedentes de pancreatitis o insuficiencia cardiaca y pregunta qué hacer ante dificultad respiratoria nueva, hinchazón, dolor articular intenso o ampollas. El equipo interpreta cada dato sin que Bitavida diagnostique la causa." ,
            interactions = "En combinación con insulina o una sulfonilurea puede aumentar el riesgo de glucosa demasiado baja. Pregunta al equipo cómo reconocerla y qué plan escrito corresponde; no ajustes esos medicamentos por tu cuenta.\n\nLa ficha describe también una interacción con digoxina que requiere vigilancia profesional. La lista educativa es parcial: lleva al médico o farmacéutico todos los productos, incluso los de venta libre." ,
            formulations = "La referencia describe comprimidos orales con diferentes concentraciones. La función renal y la indicación son datos que el profesional revisa para seleccionar el producto adecuado; Bitavida no calcula cantidades.\n\nTambién existen combinaciones con otros principios activos, como metformina. El nombre completo del envase importa porque esas fichas pueden tener precauciones adicionales." ,
            questions = "¿Qué objetivo cumple sitagliptina y cómo se revisará la función renal? ¿Qué cambios de piel, articulaciones o abdomen requieren aviso? ¿Qué plan escrito corresponde si también usa insulina o sulfonilureas? ¿El envase contiene sitagliptina sola o combinada?" ,
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Qué son las incretinas y cómo actúa la sitagliptina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Por qué se revisa la función renal?", DrugIntent.PRECAUTIONS),
                DrugRelatedQuestion("¿Qué precaución existe con insulina o sulfonilureas?", DrugIntent.INTERACTIONS),
            ),
            source = daily("Januvia: sitagliptin", "194c3718-5eb5-4cf5-85d0-2bb1ed8293b8", "Revisión 07/2026").copy(reviewedOn = "22 de noviembre de 2026"),
        ),
        card(
            id = "linagliptina", name = "Linagliptina", family = "Inhibidores DPP-4",
            aliases = listOf("linagliptin"),
            summary = "La linagliptina pertenece a los inhibidores DPP-4. Ayuda a prolongar señales del intestino que participan en el control de la glucosa.",
            use = "La ficha estadounidense describe su uso para mejorar el control de glucosa en adultos con diabetes tipo 2, junto con las medidas acordadas con el equipo de salud. El profesional explica cuál es su objetivo en el plan concreto; no se debe inferir una indicación personal a partir de esta ficha.",
            mechanism = "Después de comer, el intestino libera señales llamadas incretinas que participan en la regulación de glucosa. Una proteína llamada DPP-4 las descompone. La linagliptina inhibe DPP-4 para que esas señales permanezcan activas durante más tiempo.\n\nEsto ayuda a regular la liberación de insulina según la glucosa y reduce otra señal, el glucagón, que normalmente favorece la liberación de glucosa por el hígado. No es insulina y no funciona igual que una sulfonilurea.",
            common = "Se describen molestias de nariz y garganta. Los efectos comunicados pueden variar según si la linagliptina se estudia sola o junto con otros medicamentos; no todas las personas los presentan. Comunica molestias nuevas o persistentes para que el equipo valore su causa.\n\nCuando se combina con insulina o una sulfonilurea puede aumentar el riesgo de glucosa baja. Sus señales pueden incluir hambre, temblor, sudoración o confusión, aunque varían entre personas. Pregunta qué plan escrito corresponde." ,
            serious = "La ficha describe pancreatitis, una inflamación del páncreas. Un dolor intenso y persistente en la parte alta del abdomen, que puede extenderse hacia la espalda y presentarse con o sin vómitos, necesita valoración urgente. También se han comunicado dolor articular intenso y una enfermedad de la piel que produce ampollas.\n\nLa hinchazón de cara, labios o garganta con dificultad para respirar requiere atención urgente por posible reacción alérgica grave. Una guía no puede confirmar la causa de estos cambios ni sustituir la valoración profesional." ,
            contraindications = "Hipersensibilidad a linagliptina o componentes, incluida anafilaxia, angioedema o reacción cutánea exfoliativa.",
            precautions = "Comenta antecedentes de pancreatitis o insuficiencia cardiaca al equipo. La ficha advierte que ciertos medicamentos de esta familia se han asociado con insuficiencia cardiaca; el profesional valora síntomas nuevos como falta de aire o hinchazón. Una advertencia no equivale automáticamente a una contraindicación.\n\nLa referencia de linagliptina sola no recomienda ajustar su cantidad por función renal reducida. Esto no establece que todos los productos combinados con linagliptina tengan las mismas instrucciones: el equipo debe revisar cada componente y cada situación." ,
            interactions = "La rifampicina puede reducir la exposición a linagliptina y modificar el efecto buscado. Cuando se combina con insulina o una sulfonilurea puede aumentar el riesgo de hipoglucemia, es decir, una bajada de glucosa.\n\nComunica al médico o farmacéutico todos los productos utilizados, incluidos los de venta libre. La lista no demuestra que una combinación concreta sea segura y la aplicación no ajusta tratamientos." ,
            formulations = "La ficha consultada corresponde a comprimidos orales de linagliptina sola. También existen productos combinados con metformina u otros principios activos: su nombre completo y sus advertencias son diferentes.\n\nComprueba cuál aparece en el envase con el farmacéutico. Una instrucción renal para linagliptina sola no permite deducir la de una combinación." ,
            questions = "¿Qué objetivo tiene la linagliptina en este plan? ¿Cómo cambia el riesgo de glucosa baja con los demás medicamentos? ¿Qué molestias abdominales, articulares o de piel debemos comunicar? ¿Cómo identificar si el envase contiene una combinación?",
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo actúa la linagliptina sobre las incretinas?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué diferencia hay entre linagliptina sola y combinada?", DrugIntent.FORMULATIONS),
                DrugRelatedQuestion("¿Por qué se revisan la rifampicina y otros medicamentos?", DrugIntent.INTERACTIONS),
