        card(
            id = "pioglitazona", name = "Pioglitazona", family = "Tiazolidinedionas",
            aliases = listOf("pioglitazone"),
            summary = "La pioglitazona es una tiazolidinediona que ayuda a que el cuerpo responda mejor a la insulina que ya tiene.",
            use = "La ficha estadounidense la describe para mejorar el control de glucosa en adultos con diabetes tipo 2, junto con otras medidas del plan de atención. Su uso debe valorarse según la situación de cada persona; esta referencia no garantiza disponibilidad de una presentación mexicana.",
            mechanism = "La insulina es una hormona que facilita el uso de glucosa por los tejidos. En la diabetes tipo 2, músculo, hígado y tejido graso pueden responder menos a su señal. La pioglitazona activa una proteína reguladora llamada PPAR-gamma y mejora la sensibilidad a la insulina en esos tejidos.\n\nA diferencia de una sulfonilurea, no actúa principalmente estimulando al páncreas a liberar más insulina. Su mecanismo no elimina la necesidad de que el equipo revise el tratamiento completo.",
            common = "Se han notificado aumento de peso, hinchazón por retención de líquido, dolor de cabeza y molestias respiratorias altas. No toda hinchazón tiene la misma causa, pero un cambio nuevo o rápido conviene comunicarlo al equipo.",
            serious = "La pioglitazona puede causar o empeorar insuficiencia cardiaca: el corazón tiene dificultades para atender las necesidades de circulación del cuerpo. La retención de líquido puede aumentar ese problema. Falta de aire nueva, hinchazón importante o aumento rápido de peso requieren valoración médica pronta.\n\nTambién se describen daño hepático y cambios visuales, entre otros efectos. Piel u ojos amarillos y alteraciones visuales nuevas necesitan valoración; no permiten identificar su causa desde la aplicación.",
            contraindications = "La ficha contraindica iniciar pioglitazona en insuficiencia cardiaca avanzada de clases III o IV y usarla ante hipersensibilidad conocida al producto.",
            precautions = "El equipo puede revisar antecedentes cardiacos, retención de líquido, hígado, fracturas y problemas de vejiga. La ficha indica evitar su uso cuando hay cáncer activo de vejiga y valorar los antecedentes de esta enfermedad. Estas precauciones no significan que la persona tenga alguna de ellas.",
            interactions = "La combinación con insulina puede aumentar la retención de líquido y el riesgo de hipoglucemia. Gemfibrozilo puede aumentar la cantidad de pioglitazona en el organismo, mientras rifampicina puede reducirla. Es importante revisar todos los productos con el equipo sin hacer cambios por cuenta propia.",
            formulations = "Existen comprimidos orales y también productos que combinan pioglitazona con otros medicamentos; las advertencias de una combinación incluyen las de sus componentes. La referencia es estadounidense y no confirma comercialización mexicana.",
            questions = "¿Qué objetivo busca en este tratamiento? ¿Qué cambios de respiración, peso o hinchazón debemos comunicar? ¿Qué antecedentes de hígado, huesos o vejiga debemos revisar? ¿Influyen los otros medicamentos?",
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo ayuda la pioglitazona a responder a la insulina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué antecedentes de corazón o vejiga conviene comunicar?", DrugIntent.PRECAUTIONS),
                DrugRelatedQuestion("¿Por qué se revisa su combinación con insulina?", DrugIntent.INTERACTIONS),
            ),
            source = daily("Actos: pioglitazone", "d2ddc491-88a9-4063-9150-443b4fa4330c", "Revisión 03/2025").copy(reviewedOn = "22 de noviembre de 2026"),
        ),
        card(
            id = "rosiglitazona", name = "Rosiglitazona · documentación histórica", family = "Tiazolidinedionas",
            aliases = listOf("rosiglitazona", "rosiglitazone"),
            summary = "La rosiglitazona es una tiazolidinediona que ayuda a algunos tejidos a responder a la insulina. Esta ficha solo describe un documento histórico de 2013." ,
            use = "La referencia archivada de 2013 describe su uso para mejorar el control de la glucosa en diabetes tipo 2. Es documentación histórica: no confirma condiciones regulatorias, indicaciones ni disponibilidad actuales en México o en otro país.\n\nEl equipo de salud debe revisar la información vigente para cualquier producto concreto; esta ficha no recomienda iniciar, continuar ni cambiar un tratamiento." ,
            mechanism = "La insulina es una hormona que ayuda a que el organismo aproveche la glucosa. La ficha histórica describe que rosiglitazona activa un receptor llamado PPAR-gamma, presente en tejidos como el músculo, la grasa y el hígado. Ese receptor participa en la respuesta de esos tejidos a la insulina.\n\nEl efecto descrito es diferente del de una sulfonilurea que estimula al páncreas para liberar insulina. Esta explicación no indica qué tratamiento corresponde a una persona." ,
            common = "La ficha histórica describe hinchazón o edema y aumento de peso; también se notificaron infección respiratoria y dolor de cabeza. La hinchazón puede reflejar acumulación de líquido, pero un síntoma por sí solo no permite conocer su causa.\n\nComunica al equipo un cambio nuevo o importante de peso, respiración o hinchazón para que determine qué evaluación corresponde." ,
            serious = "El documento histórico advierte que las tiazolidinedionas pueden causar o empeorar insuficiencia cardiaca en algunas personas, al favorecer la retención de líquidos. Falta de aire nueva, aumento rápido de peso o hinchazón importante necesitan atención profesional pronta.\n\nLa referencia también describe fracturas y edema macular, acumulación de líquido en la región central de la retina. Los cambios de visión deben comunicarse para valorar su causa. Estas advertencias necesitan cotejarse con información vigente." ,
            contraindications = "La ficha histórica contraindica iniciar tratamiento en insuficiencia cardiaca avanzada NYHA III o IV.",
            precautions = "Según el documento de 2013, el equipo debía valorar la función del hígado, la retención de líquidos y el riesgo de fracturas. En una persona mayor, anotar cambios en respiración, hinchazón, peso o visión puede ayudar a explicar lo observado durante la consulta.\n\nNo atribuyas automáticamente esos cambios al medicamento; la ficha archivada requiere contraste con documentación actual y revisión clínica." ,
            interactions = "La ficha histórica describe que gemfibrozilo puede aumentar la exposición a rosiglitazona y rifampicina reducirla. También advierte sobre riesgos de retención de líquidos y corazón al combinarla con insulina.\n\nEstas interacciones no son una lista completa ni establecen las condiciones actuales. Lleva al equipo todos los envases y pide que revise la documentación vigente antes de cualquier cambio." ,
            formulations = "La fuente archivada describía comprimidos orales. El archivo no confirma que una formulación se comercialice actualmente ni que esté autorizada en México. El nombre y la presentación deben verificarse con un profesional y fuentes regulatorias actuales." ,
            questions = "¿Cuál es la información regulatoria vigente para este producto en nuestro país? ¿Qué objetivo tendría en este caso? ¿Qué cambios de respiración o hinchazón deben comunicarse? ¿Debemos revisar otros medicamentos o antecedentes del corazón y la vista?" ,
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Qué describe el documento histórico sobre la acción de rosiglitazona?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué interacciones describía la ficha de 2013?", DrugIntent.INTERACTIONS),
                DrugRelatedQuestion("¿Qué limitaciones tiene la información sobre disponibilidad?", DrugIntent.FORMULATIONS),
            ),
            source = fda("Rosiglitazone maleate tablets: archivo regulatorio", "2013/076747Orig1s000lbl.pdf", "Archivo 2013; no se presenta como ficha vigente").copy(reviewedOn = "22 de noviembre de 2026"),
            status = "Ficha documental histórica. Vigencia y disponibilidad actuales no verificadas. Pendiente de revisión clínica.",
        ),
        card(
            id = "repaglinida", name = "Repaglinida", family = "Meglitinidas",
            aliases = listOf("repaglinide"),
            summary = "La repaglinida ayuda al páncreas a liberar insulina y su uso está relacionado con las comidas." ,
            use = "La ficha estadounidense describe repaglinida como apoyo para mejorar el control de glucosa en adultos con diabetes tipo 2, junto con las medidas de alimentación y actividad física acordadas con el equipo. Su acción se relaciona con las comidas, por lo que conviene preguntar qué hacer si cambian los horarios, se omite una comida o se olvida una administración.\n\nLa referencia indica que no se utiliza para tratar diabetes tipo 1 ni cetoacidosis diabética, una complicación que requiere atención médica. El profesional explica el plan individual; esta información no establece cantidades, horarios ni disponibilidad en México." ,
            mechanism = "El páncreas tiene células que liberan insulina, la hormona que ayuda a que la glucosa pase desde la sangre a los tejidos. La repaglinida estimula esas células para que liberen insulina; necesita que todavía puedan producirla.\n\nSu efecto se relaciona con las comidas. Como aumenta la liberación de insulina, puede bajar demasiado la glucosa, en particular si cambia la alimentación o se combina con otros medicamentos que también la reducen." ,
            common = "La hipoglucemia significa que la glucosa baja demasiado. Puede notarse como hambre, temblor, sudoración, mareo o confusión, aunque no todas las personas reconocen las señales con facilidad. Pregunta al equipo qué plan escrito corresponde a la persona que acompañas.\n\nTambién se describen infecciones respiratorias altas, dolor de cabeza y molestias articulares. Un síntoma aislado no demuestra que el medicamento lo haya causado." ,
            serious = "Una hipoglucemia grave puede causar confusión importante, convulsiones o pérdida de conciencia y requiere atención urgente. Pregunta al equipo cómo reconocerla y qué hacer según el plan individual; no esperes a que aparezcan todas las señales.\n\nSe describen reacciones alérgicas importantes. La hinchazón de cara o garganta o la dificultad para respirar requiere atención urgente." ,
            contraindications = "Uso simultáneo de gemfibrozilo y alergia a repaglinida o excipientes.",
            precautions = "Las comidas irregulares o insuficientes y la enfermedad hepática o renal pueden influir en el riesgo de hipoglucemia. En personas mayores algunas señales pueden ser difíciles de identificar; comenta cambios en alimentación, estado general o capacidad para reconocerlas.\n\nLa indicación está vinculada a las comidas. Solicita instrucciones escritas para situaciones como una comida omitida o una administración olvidada; no inventes un horario ni ajustes el tratamiento por cuenta propia." ,
            interactions = "Gemfibrozilo está contraindicado con repaglinida en la ficha consultada. Clopidogrel y ciclosporina pueden aumentar la exposición a repaglinida; rifampicina puede reducirla. Algunos betabloqueadores pueden hacer menos visibles señales de glucosa baja.\n\nEsta lista es parcial. Entrega al médico o farmacéutico una lista de todos los productos, incluidos los de venta libre, antes de cualquier cambio." ,
            formulations = "La referencia describe comprimidos orales vinculados a las comidas. La indicación recibida explica cuándo corresponde administrarlos; la aplicación no deduce horarios. Comprueba el nombre y la presentación con el equipo antes de cualquier sustitución." ,
            questions = "¿Cómo ayuda este medicamento alrededor de las comidas? ¿Qué plan escrito debemos seguir si cambia una comida o se olvida una administración? ¿Qué señales de glucosa baja debemos reconocer? ¿Se revisaron clopidogrel, gemfibrozilo y los demás medicamentos?" ,
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo se relaciona repaglinida con las comidas?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Por qué debemos consultar ante una comida omitida?", DrugIntent.PRECAUTIONS),
                DrugRelatedQuestion("¿Qué interacción se describe con gemfibrozilo?", DrugIntent.INTERACTIONS),
            ),
            source = daily("Repaglinide tablets", "cb995e92-295e-4638-a064-978211f5afe1", "Actualización 02/05/2025").copy(reviewedOn = "22 de noviembre de 2026"),
        ),
        card(
