        card(
            id = "acarbosa", name = "Acarbosa", family = "Inhibidores alfa-glucosidasa",
            aliases = listOf("acarbose"),
            summary = "La acarbosa es un medicamento oral que retrasa la digestión de algunos carbohidratos y, con ello, la llegada de glucosa a la sangre después de comer.",
            use = "La ficha estadounidense la describe como apoyo para el control de glucosa en adultos con diabetes tipo 2. Su objetivo en una persona concreta debe explicarlo el equipo tratante. La referencia no confirma la disponibilidad de una presentación determinada en México.",
            mechanism = "Los carbohidratos de los alimentos se descomponen en azúcares más simples antes de absorberse. Algunas enzimas del intestino, llamadas alfa-glucosidasas, participan en esa descomposición. La acarbosa frena su acción, de modo que determinados carbohidratos tardan más en transformarse y absorberse.\n\nSu efecto se relaciona especialmente con el aumento de glucosa después de comer. No es insulina y no actúa principalmente haciendo que el páncreas libere más insulina.",
            common = "Pueden aparecer gases, distensión, diarrea o dolor abdominal. Parte de los carbohidratos no digeridos llega al intestino grueso, donde las bacterias pueden fermentarlos y producir gas. La intensidad varía y las molestias persistentes o intensas deben comentarse.",
            serious = "La ficha describe alteraciones hepáticas y problemas intestinales importantes. Piel u ojos amarillos, distensión intensa o dolor abdominal persistente requieren valoración médica.\n\nPor su mecanismo, la acarbosa sola generalmente no provoca hipoglucemia; combinada con insulina o sulfonilureas puede aumentar ese riesgo. La confusión importante, convulsiones o pérdida de conciencia necesitan atención inmediata.",
            contraindications = "La ficha enumera hipersensibilidad, cetoacidosis, cirrosis, enfermedad inflamatoria intestinal, ulceración de colon, obstrucción intestinal o predisposición a ella y ciertos trastornos crónicos de digestión o absorción.",
            precautions = "El equipo puede valorar la función hepática y renal y las enfermedades digestivas previas. En una persona mayor es útil comunicar cambios de alimentación o molestias intestinales que dificulten la vida cotidiana, sin atribuirles automáticamente una causa.",
            interactions = "Las enzimas digestivas y algunos adsorbentes intestinales pueden interferir con su efecto. La ficha también describe cambios en la exposición a digoxina y mayor riesgo de hipoglucemia cuando se combina con insulina o sulfonilureas.\n\nLa acarbosa retrasa la descomposición de la sacarosa, el azúcar común. Por ello conviene solicitar al equipo un plan escrito específico para reconocer y atender una posible hipoglucemia si se usan otros tratamientos; no todas las fuentes de azúcar actúan igual en este contexto.",
            formulations = "Se presenta en comprimidos orales. La información consultada es estadounidense; no establece que una marca o presentación concreta esté disponible en México.",
            questions = "¿Qué efecto se busca después de las comidas? ¿Qué molestias digestivas debemos comunicar? Si usa insulina o una sulfonilurea, ¿qué plan escrito de hipoglucemia corresponde? ¿Hay que revisar sus otros medicamentos o el hígado?",
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo retrasa la acarbosa la digestión de carbohidratos?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Por qué pueden aparecer gases o distensión?", DrugIntent.SIDE_EFFECTS),
                DrugRelatedQuestion("¿Por qué pedir un plan específico para una baja de glucosa?", DrugIntent.INTERACTIONS),
            ),
            source = daily("Acarbose tablets", "352dd336-d3f9-4ac5-a000-91d3aef7aca3", "Actualización 19/07/2024").copy(reviewedOn = "22 de noviembre de 2026"),
        ),
        card(
            id = "miglitol", name = "Miglitol", family = "Inhibidores alfa-glucosidasa",
            aliases = listOf("miglitol tablets"),
            summary = "El miglitol retrasa la transformación de algunos carbohidratos en azúcares que pueden absorberse en el intestino." ,
            use = "La ficha estadounidense describe miglitol como apoyo para mejorar el control de glucosa en adultos con diabetes tipo 2, junto con las medidas de alimentación y actividad física acordadas con el equipo. Su efecto se relaciona especialmente con el aumento de glucosa después de comer, porque retrasa la digestión de ciertos carbohidratos.\n\nNo todas las personas necesitan el mismo tratamiento. El equipo explica el objetivo y revisa los demás medicamentos; la referencia estadounidense consultada no demuestra disponibilidad ni autorización en México." ,
            mechanism = "Los carbohidratos de los alimentos deben dividirse en azúcares más simples antes de absorberse. En el intestino, unas enzimas llamadas alfa-glucosidasas participan en esa transformación. El miglitol frena esas enzimas, por lo que ciertos azúcares tardan más en llegar a la sangre después de comer.\n\nNo es insulina y no actúa principalmente estimulando al páncreas para liberar más insulina. Su acción también afecta la descomposición de la sacarosa, el azúcar común." ,
            common = "Pueden aparecer gases, diarrea o molestias abdominales. La ficha describe estas molestias digestivas entre las reacciones observadas con el producto.\n\nNo todas las personas experimentan estas molestias; comunica al equipo si son intensas, persisten o dificultan comer y beber." ,
            serious = "Dolor abdominal intenso y persistente, distensión marcada o vómitos requieren valoración profesional, especialmente si existe una enfermedad intestinal previa. Una ficha no puede establecer la causa del síntoma.\n\nEl miglitol solo no suele provocar hipoglucemia; al combinarse con insulina o sulfonilureas puede presentarse. Confusión importante, convulsiones o pérdida de conciencia necesitan atención urgente." ,
            contraindications = "Cetoacidosis; enfermedad inflamatoria intestinal, ulceración de colon, obstrucción o predisposición; trastornos digestivos o de absorción importantes; hipersensibilidad.",
