    private fun daily(document: String, setId: String, version: String) = DrugReference(
        institution = "NLM / DailyMed", document = document,
        url = "https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=$setId",
        version = version,
    )

    private fun fda(document: String, label: String, version: String) = DrugReference(
        institution = "FDA", document = document,
        url = "https://www.accessdata.fda.gov/drugsatfda_docs/label/$label",
        version = version,
    )

    /** Structure only; all clinical text is supplied separately for each product/formulation. */
    private fun card(
        id: String, name: String, family: String, aliases: List<String>, summary: String,
        use: String, mechanism: String, common: String, serious: String,
        contraindications: String, precautions: String, interactions: String,
        formulations: String, questions: String, source: DrugReference,
        status: String = "Información educativa pendiente de revisión clínica.",
        confirmationAliases: List<String> = emptyList(),
        relatedQuestions: List<DrugRelatedQuestion> = emptyList(),
    ) = DrugEducation(
        id = id, name = name, family = family, aliases = aliases, summary = summary,
        sections = listOf(
            DrugEducationSection(DrugIntent.IDENTIFY, "Qué es", "$name pertenece a $family. " +
                if (aliases.isEmpty()) "No se añaden otros nombres." else "Nombres alternativos: ${aliases.joinToString()}."),
            DrugEducationSection(DrugIntent.PURPOSE, "Para qué se utiliza", use),
            DrugEducationSection(DrugIntent.MECHANISM, "Cómo funciona", mechanism),
            DrugEducationSection(DrugIntent.SIDE_EFFECTS, "Efectos frecuentes y otros notificados", common),
            DrugEducationSection(DrugIntent.SIDE_EFFECTS, "Señales importantes", serious),
            DrugEducationSection(DrugIntent.CONTRAINDICATIONS, "Contraindicaciones documentadas", contraindications),
            DrugEducationSection(DrugIntent.PRECAUTIONS, "Precauciones", precautions),
            DrugEducationSection(DrugIntent.INTERACTIONS, "Interacciones relevantes · lista no exhaustiva", interactions),
            DrugEducationSection(DrugIntent.FORMULATIONS, "Formulación y vía", formulations),
            DrugEducationSection(DrugIntent.CONSULTATION, "Preguntas para la consulta", questions),
        ),
        sources = listOf(source),
        statusNote = status,
        confirmationAliases = confirmationAliases,
        relatedQuestions = relatedQuestions,
    )
}
